const form=document.querySelector('#auth-form'),status=document.querySelector('.auth-status');
const fromLink=new URLSearchParams(location.search).get('verified')==='1';
if(!fromLink){form.hidden=true;status.hidden=false;status.textContent='Open the link in your reset email to choose a new password.';form.before(status);}
form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;status.hidden=false;try{const response=await fetch('/api/auth/reset-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:form.elements.password.value})});const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to reset your password.');sessionStorage.removeItem('uniify-reset-email');form.reset();status.textContent='Password updated. You can now sign in.';form.querySelector('.auth-field').hidden=true;button.hidden=true;}catch(error){status.textContent=error.message;}finally{form.elements.password.value='';button.disabled=false;status.focus();}};
